import torch
kernel, reference = load_task()
def run(shape, beta, dt, T=1.0, labels=None, ign=-100, up=None, acc=None, seed=0, lay=None):
    BT,Hs,Ht,V = shape
    spec={'tensors': {'student_input': {'shape': [BT,Hs], 'dtype': dt},
     'student_weight': {'shape': [V,Hs], 'dtype': dt, 'init': {'kind': 'randn', 'std': 0.25}},
     'teacher_input': {'shape': [BT,Ht], 'dtype': dt},
     'teacher_weight': {'shape': [V,Ht], 'dtype': dt, 'init': {'kind': 'randn', 'std': 0.25}}},
     'kwargs': {'jsd_beta': beta,'temperature':T,'ignore_index':ign,'accum_dtype':acc},
     'upstream': up or {'kind':'ones'}, 'seed': seed}
    if lay:
        for k in ('student_input','teacher_input','student_weight'): spec['tensors'][k]['layout']=lay
    if labels is not None:
        spec['tensors']['shift_labels']={'shape':[BT],'dtype':'int64','init':labels}
    return spec
cases=[]
for beta in (0.0,0.4,1.0):
  for dt in ('float32','bfloat16'):
    cases.append(dict(shape=(20,16,24,50),beta=beta,dt=dt,labels={'kind':'randint','low':-1,'high':50} ,ign=-1,T=1.7))
    cases.append(dict(shape=(20,16,24,50),beta=beta,dt=dt,labels={'kind':'constant','value':3},ign=3))
    cases.append(dict(shape=(20,16,24,50),beta=beta,dt=dt,lay='row_strided:2'))
    cases.append(dict(shape=(20,16,24,50),beta=beta,dt=dt,acc='float32',up={'kind':'scalar','value':-1.5}))
    cases.append(dict(shape=(9,200,24,6000),beta=beta,dt=dt,up={'kind':'randn'} ))
for c in cases:
    try:
        r=grad_compare(kernel,reference,build_inputs(run(**c)))
        bad=[(i['name'],i['ratio']) for i in r['items'] if not i['passed']]
        print(c['beta'],c['dt'],c.get('ign'),c.get('lay'),c['shape'],r['pass'],bad, [round(i['ratio'],3) for i in r['items']])
    except Exception as e:
        print(c,'ERR',repr(e)[:300])"}

